  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    id2node = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    retained = set(id2node.keys())
    # Process nodes bottom-up (deeper first), tie by id
    order = sorted(retained, key=lambda nid: (-id2node[nid]['depth'], nid))
    removed_order = []
    for nid in order:
        if nid not in retained:
            continue
        node = id2node[nid]
        if not node['removable']:
            continue
        if nid == 'root':   # root is never removed (also typically in required_symbols)
            continue
        sym = node['symbol']
        # If node's symbol is required, we need at least one other retained node with that symbol
        if sym in required_symbols:
            other = [oid for oid in retained if id2node[oid]['symbol'] == sym and oid != nid]
            if not other:
                continue
        # Check for retained children
        has_retained_child = any(cid in retained for cid in children.get(nid, []))
        if has_retained_child:
            continue
        # Remove the node
        retained.remove(nid)
        removed_order.append(nid)
    # Collect retained ids sorted (alphabetically)
    retained_ids = sorted(retained)
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_ids}"
}
